// OdpsLexerInit initializes any static state used to implement OdpsLexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewOdpsLexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func OdpsLexerInit() {
	staticData := &OdpsLexerLexerStaticData
	staticData.once.Do(odpslexerLexerInit)
}

// NewOdpsLexer produces a new lexer instance for the optional input antlr.CharStream.
func NewOdpsLexer(input antlr.CharStream) *OdpsLexer {
	OdpsLexerInit()
	l := new(OdpsLexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &OdpsLexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "OdpsLexer.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

